async def load_all(ids):
    tasks = [asyncio.create_task(fetch_report(i)) for i in ids]   # starts now
    try:
        return await asyncio.gather(*tasks)                       # collects later
    except BaseException:
        for task in tasks:
            task.cancel()                                         # request sibling cancellation
        await asyncio.gather(*tasks, return_exceptions=True)      # drain before re-raising
        raise
